using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using Newtonsoft.Json.Linq;using Orbit;
class HorizonTests {
 static int n;static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+(++n)+" "+name);}static void Fails(Action a,string name){try{a();}catch{Check(true,name);return;}throw new Exception(name+" not rejected");}
 static async Task Main(){
  Check(HorizonBridge.Id("Our Pack 1.2")=="Our Pack 1.2","pack id accepts spaces and versions");Fails(()=>HorizonBridge.Id("../evil"),"pack traversal rejected");Fails(()=>HorizonBridge.Id("--help"),"switch injection rejected");Fails(()=>HorizonBridge.Query("test; echo hi"),"query shell metacharacters rejected");
  Check(HorizonBridge.Address("192.168.1.3:25565")=="192.168.1.3:25565","server address allowed");Fails(()=>HorizonBridge.Address("--world"),"server switch injection rejected");Check(HorizonBridge.Invite("abc/def+123==")=="abc/def+123==","encoded invitation accepted");Fails(()=>HorizonBridge.Invite("--world"),"invitation switch injection rejected");
  var clean=HorizonBridge.Printable("{\"token\":\"PRIVATE\",\"nested\":{\"invite\":\"SECRET\",\"name\":\"example\"}}");Check(!clean.Contains("PRIVATE")&&!clean.Contains("SECRET")&&clean.Contains("example"),"JSON secrets removed");
  var state=HorizonBridge.SafeState("{\"player\":{\"position\":[1,2,3],\"health\":19,\"food\":18,\"name\":\"PRIVATE\"},\"chat\":\"SECRET\",\"token\":\"OTHER\",\"dimension\":\"minecraft:overworld\"}");Check(state.Contains("position")&&state.Contains("health")&&state.Contains("minecraft:overworld")&&!state.Contains("PRIVATE")&&!state.Contains("SECRET")&&!state.Contains("OTHER"),"state is a strict allowlist");Fails(()=>HorizonBridge.SafeState("{\"chat\":\"secret\"}"),"unknown state not forwarded");
  string hash=new string('a',64);var rows=JArray.Parse("[{\"tag_name\":\"v2\",\"assets\":[]},{\"tag_name\":\"launcher@0.3.0\",\"assets\":[{\"name\":\"horizon-launcher-windows-x64.zip\",\"digest\":\"sha256:"+hash+"\",\"size\":42,\"browser_download_url\":\"https://github.com/horizon-rust/horizon/releases/download/launcher%400.3.0/horizon-launcher-windows-x64.zip\"}]}]");var release=HorizonInstaller.SelectRelease(rows);Check((string)release["tag"]=="launcher@0.3.0"&&((string)release["digest"])==hash,"official launcher release with digest selected");((JObject)rows[1]["assets"][0])["digest"]=null;Fails(()=>HorizonInstaller.SelectRelease(rows),"download without SHA256 rejected");
  var root=Path.Combine(Path.GetTempPath(),"orbit-horizon-test-"+Guid.NewGuid());Directory.CreateDirectory(root);try{
   var mod=Path.Combine(root,"test.hmod");using(var z=ZipFile.Open(mod,ZipArchiveMode.Create))using(var w=new StreamWriter(z.CreateEntry("horizon-mod.toml").Open()))w.Write("id = 'test'");HorizonBridge.CheckHmod(mod);var game=Path.Combine(root,"game");Directory.CreateDirectory(game);HorizonBridge.AddHmod(mod,game);Check(File.Exists(Path.Combine(game,"horizon-mods","test.hmod"))&&File.Exists(mod),"native hmod copied without deleting source");Fails(()=>HorizonBridge.AddHmod(mod,game),"existing native hmod not overwritten");var broken=Path.Combine(root,"broken.hmod");File.WriteAllText(broken,"partial");Fails(()=>HorizonBridge.CheckHmod(broken),"incomplete native hmod rejected");
   if(!OperatingSystem.IsWindows()){
    var fake=Path.Combine(root,"horizon-launcher.exe");File.WriteAllText(fake,"#!/bin/sh\nprintf '%s\\n' \"$HORIZON_LAUNCHER_HOME\" \"$1\" \"$2\"\n");File.SetUnixFileMode(fake,UnixFileMode.UserRead|UnixFileMode.UserWrite|UnixFileMode.UserExecute);
    var r=await HorizonBridge.Run(fake,root,new[]{"mods", "name with spaces"},5000);Check(r.code==0&&r.output.Contains("name with spaces")&&r.output.Contains(root),"isolated process passes home and quoted arguments");
    var fail=Path.Combine(root,"fail.exe");File.WriteAllText(fail,"#!/bin/sh\nprintf 'bad version' >&2\nexit 7\n");File.SetUnixFileMode(fail,UnixFileMode.UserRead|UnixFileMode.UserWrite|UnixFileMode.UserExecute);r=await HorizonBridge.Run(fail,root,new[]{"versions"},5000);Check(r.code==7&&r.error.Contains("bad version"),"exit and real stderr are captured");
   }
  }finally{Directory.Delete(root,true);}Console.WriteLine("HorizonTests: "+n+" passed");
 }
}
